      break;
    }
    if (!playerId) return; // no player
    const localPeerState = net?.getLocalPeer?.()?.state;
    if (Number.isFinite(localPeerState?.x) && Number.isFinite(localPeerState?.y)) {
      pos = {
        ...pos,
