+import { World, composeScheduler } from '../../lib/ecs-js/index.js';
+import { spawnPlayer } from '../spawner.js';
+import { Input, Position, Facing, Health } from '../components/index.js';
+import { createMovementSystem } from '../systems/movementSystem.js';
+
+export function createArenaSimWorld({ seed, grid, spawns = [] }) {
+  const world = new World({ seed });
+  const playerByPeer = new Map();
+  const movementSystem = createMovementSystem({ grid });
+
+  world.system(movementSystem, 'simulate');
+  world.setScheduler(composeScheduler('simulate'));
+
+  function addPlayer(peerId, spawnIndex = 0) {
+    if (playerByPeer.has(peerId)) return playerByPeer.get(peerId);
+
+    const spawn = spawns[spawnIndex % Math.max(1, spawns.length)] || { x: 1000, y: 1000 };
+    const entityId = spawnPlayer(world, spawn.x, spawn.y);
+    playerByPeer.set(peerId, entityId);
+    return entityId;
+  }
+
+  function removePlayer(peerId) {
+    const entityId = playerByPeer.get(peerId);
+    if (entityId == null) return;
+    playerByPeer.delete(peerId);
+    if (world.alive.has(entityId)) world.destroy(entityId);
+  }
+
+  function setPlayerInput(peerId, inputFrame) {
+    const entityId = playerByPeer.get(peerId);
+    if (entityId == null || !world.has(entityId, Input)) return;
+
+    const input = world.get(entityId, Input);
+    input.moveX = inputFrame.moveX;
+    input.moveY = inputFrame.moveY;
+    input.aimX = inputFrame.aimX;
+    input.aimY = inputFrame.aimY;
+    input.fire = inputFrame.fire;
+  }
+
+  function step(dt) {
+    world.tick(dt);
+  }
+
+  function getPlayerSnapshot(peerId) {
+    const entityId = playerByPeer.get(peerId);
+    if (entityId == null || !world.alive.has(entityId)) return null;
+
+    const pos = world.get(entityId, Position);
+    const facing = world.has(entityId, Facing) ? world.get(entityId, Facing) : null;
+    const health = world.has(entityId, Health) ? world.get(entityId, Health) : null;
+    return {
+      entityId,
+      state: {
+        x: pos.x,
+        y: pos.y,
+        facing: facing?.angle ?? 0,
+        hp: health?.hp ?? null,
+        maxHp: health?.maxHp ?? null,
+      },
+    };
+  }
+
+  return {
+    addPlayer,
+    getPlayerSnapshot,
+    removePlayer,
+    setPlayerInput,
+    step,
+    world,
+  };
+}
